/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { MatrixElement, MatrixSymbol, Sum, add, convertIndexedToArray, mul, rational, symbols } from '../../../../src';
import { sympyStr } from '../../../sympy-str';

describe("doctests of sympy.tensor.array.expressions.from_indexed_to_array", () => {
  it("convert_indexed_to_array(expr)", () => {
    const [d, i] = symbols('d i');
    expect(sympyStr(convertIndexedToArray(Sum(MatrixElement(new MatrixSymbol('M', d, d), i, i), [i, rational(0), add(-1, d)])))).toBe('ArrayContraction(M, (0, 1))');
  });
  it("convert_indexed_to_array(expr) (2)", () => {
    const [d, i] = symbols('d i');
    expect(sympyStr(convertIndexedToArray(MatrixElement(new MatrixSymbol('M', d, d), i, i)))).toBe('ArrayDiagonal(M, (0, 1))');
  });
  it("convert_indexed_to_array(expr) (3)", () => {
    const [d, i, j, k] = symbols('d i j k');
    expect(sympyStr(convertIndexedToArray(Sum(mul(MatrixElement(new MatrixSymbol('M', d, d), i, j), MatrixElement(new MatrixSymbol('N', d, d), j, k)), [j, rational(0), add(-1, d)])))).toBe('ArrayContraction(ArrayTensorProduct(M, N), (1, 2))');
  });
  it("convert_indexed_to_array(expr, first_indices=[k])", () => {
    const [d, i, j, k] = symbols('d i j k');
    expect(sympyStr(convertIndexedToArray(Sum(mul(MatrixElement(new MatrixSymbol('M', d, d), i, j), MatrixElement(new MatrixSymbol('N', d, d), j, k)), [j, rational(0), add(-1, d)]), [k]))).toBe('ArrayContraction(ArrayTensorProduct(N, M), (0, 3))');
  });
});
